#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int M1=998244353, M2=1e9+7;
const int MAX_SIZE=2e6, LIMIT=1e6;
ll n_value,c_value;
int total_count,final_answer,limit_depth,pw_array[MAX_SIZE],sum_array[MAX_SIZE];
vector<int> data_vectors[MAX_SIZE];

inline int subtract_mod(int x,int y,int m){return (x-y<0)?x-y+m:x-y;}
inline int add_mod(int x,int y,int m){return (x+y>=m)?x+y-m:x+y;}
inline void generate(int depth,int val){
	if(val<=n_value){
		++total_count;int x=subtract_mod(total_count,val,M1);
		data_vectors[depth-1].push_back(x);sum_array[depth-1]=add_mod(sum_array[depth-1],x,M2);
	}
	if(depth>6) return;
	for(int i=0;i<=9;++i) generate(depth+1,val*10+i);
}
inline void compute(int depth,ll current){
	if(current>n_value) return;
	if(depth>1){
		if(10ll*current*LIMIT>n_value && 1ll*(current+1)*LIMIT-1<=n_value){
			for(int i=0;i<7;++i){
				int x=((c_value-1ll*current*pw_array[i])%M1+M1)%M1;
				int p=lower_bound(data_vectors[i].begin(),data_vectors[i].end(),M1-x)-data_vectors[i].begin();
				final_answer=add_mod(final_answer,add_mod(1ll*x*data_vectors[i].size()%M2,sum_array[i],M2),M2);
				final_answer=subtract_mod(final_answer,1ll*M1*(data_vectors[i].size()-p)%M2,M2);
			}
			c_value+=total_count;
			return;
		}
		++c_value;final_answer=add_mod(final_answer,((c_value-current)%M1+M1)%M1,M2);
	}
	for(int i=(depth==1?1:0);i<=9;++i) compute(depth+1,current*10+i);
}
int main(){
	scanf("%lld",&n_value);
	pw_array[0]=1;for(int i=1;i<9;++i) pw_array[i]=10*pw_array[i-1];
	generate(1,0);
	for(int i=0;i<7;++i)
		sort(data_vectors[i].begin(),data_vectors[i].end());
	compute(1,0);
	printf("%d\n",final_answer);
	return 0;
}
